#include <climits>
using namespace std;

int main() {
    int N;
    cin >> N;
    vector<pair<int, int>> mackerels;
    vector<pair<int, int>> sardines;
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    // Compute initial bounding rectangle for mackerels
    int x_min_m = INT_MAX;
    int x_max_m = INT_MIN;
    int y_min_m = INT_MAX;
    int y_max_m = INT_MIN;
    for (auto& p : mackerels) {
        x_min_m = min(x_min_m, p.first);
        x_max_m = max(x_max_m, p.first);
        y_min_m = min(y_min_m, p.second);
        y_max_m = max(y_max_m, p.second);
    }
    vector<tuple<int, int, int, int>> candidates;
    // Add the initial candidate
    candidates.push_back({x_min_m, x_max_m, y_min_m, y_max_m});

    // Generate additional candidates
    for (auto& s : sardines) {
        int sx = s.first;
        int sy = s.second;
        // Check if the sardine is in the initial rectangle
        bool in_rect = (sx >= x_min_m && sx <= x_max_m) && (sy >= y_min_m && sy <= y_max_m);
        if (in_rect) {
            // Generate four new candidates
            // 1. adjust x_min to s.x + 1
            int new_x_min = sx + 1;
            int new_x_max = x_max_m;
            int new_y_min = y_min_m;
            int new_y_max = y_max_m;
            if (new_x_min <= new_x_max && new_y_min <= new_y_max) {
                candidates.push_back({new_x_min, new_x_max, new_y_min, new_y_max});
            }
            // 2. adjust x_max to s.x - 1
            new_x_min = x_min_m;
            new_x_max = sx - 1;
            if (new_x_min <= new_x_max && new_y_min <= new_y_max) {
                candidates.push_back({new_x_min, new_x_max, new_y_min, new_y_max});
            }
            // 3. adjust y_min to s.y + 1
            new_y_min = sy + 1;
            new_y_max = y_max_m;
            if (new_x_min <= new_x_max && new_y_min <= new_y_max) {
                candidates.push_back({new_x_min, new_x_max, new_y_min, new_y_max});
            }
            // 4. adjust y_max to s.y - 1
            new_y_min = y_min_m;
            new_y_max = sy - 1;
            if (new_x_min <= new_x_max && new_y_min <= new_y_max) {
                candidates.push_back({new_x_min, new_x_max, new_y_min, new_y_max});
            }
        }
    }

    // Evaluate all candidates to find the best one
    int best_score = 0;
    tuple<int, int, int, int> best_rect = {0, 0, 0, 0};
    for (auto& c : candidates) {
        int x_min = get<0>(c);
        int x_max = get<1>(c);
        int y_min = get<2>(c);
        int y_max = get<3>(c);

        int a = 0;
        for (auto& p : mackerels) {
            if (p.first >= x_min && p.first <= x_max && p.second >= y_min && p.second <= y_max) {
                a++;
            }
        }

        int b = 0;
        for (auto& p : sardines) {
            if (p.first >= x_min && p.first <= x_max && p.second >= y_min && p.second <= y_max) {
                b++;
            }
        }

        int score = max(0, a - b + 1);
        if (score > best_score) {
            best_score = score;
            best_rect = c;
        }
    }

    // Output the best rectangle
    int x_min_rect = get<0>(best_rect);
    int x_max_rect = get<1>(best_rect);
    int y_min_rect = get<2>(best_rect);
    int y_max_rect = get<3>(best_rect);

    cout << 4 << endl;
    cout << x_min_rect << " " << y_min_rect << endl;
    cout << x_max_rect << " " << y_min_rect << endl;
    cout << x_max_rect << " " << y_max_rect << endl;
    cout << x_min_rect << " " << y_max_rect << endl;

    return 0;
}

