            best_box_y1 = y1;
            best_box_x2 = x2;
            best_box_y2 = y2;
        }
    }

    // Ensure the box is non-degenerate
    int x1 = best_box_x1;
    int y1 = best_box_y1;
    int x2 = best_box_x2;
    int y2 = best_box_y2;

    // Adjust if necessary to make it a valid rectangle
    if (x1 >= x2) {
        x2 = x1 + 1;
    }
    if (y1 >= y2) {
        y2 = y1 + 1;
    }

