#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>
using namespace std;

struct Point {
    int x, y;
    bool is_mackerel;
};

int main() {
    int N;
    cin >> N;
    vector<Point> all_points(2 * N);
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        all_points[i].x = x;
        all_points[i].y = y;
        all_points[i].is_mackerel = (i < N);
    }

    // Separate mackerels and sardines
    vector<Point> mackerels;
    vector<Point> sardines;
    for (int i = 0; i < 2 * N; ++i) {
        if (i < N) {
            mackerels.push_back(all_points[i]);
        } else {
            sardines.push_back(all_points[i]);
        }
    }

    // Compute bounding box for mackerels
    int x_min_m = INT_MAX;
    int x_max_m = INT_MIN;
    int y_min_m = INT_MAX;
    int y_max_m = INT_MIN;
    for (const auto& p : mackerels) {
        if (p.x < x_min_m) x_min_m = p.x;
        if (p.x > x_max_m) x_max_m = p.x;
        if (p.y < y_min_m) y_min_m = p.y;
        if (p.y > y_max_m) y_max_m = p.y;
    }

    // Function to count points in rectangle
    auto count_points = [](int x1, int x2, int y1, int y2, const vector<Point>& points) -> int {
        int count = 0;
        for (const auto& p : points) {
            if (p.x >= x1 && p.x <= x2 && p.y >= y1 && p.y <= y2) {
                count++;
            }
        }
        return count;
    };

    // Generate candidates
    vector<vector<int>> candidates;

    // Add original bounding box
    int x1_orig = x_min_m;
    int x2_orig = x_max_m;
    int y1_orig = y_min_m;
    int y2_orig = y_max_m;
    if (x1_orig < x2_orig && y1_orig < y2_orig) {
        vector<int> rect = {x1_orig, x2_orig, y1_orig, y2_orig};
        candidates.push_back(rect);
    }

    // For each sardine, add adjusted rectangles
    for (const auto& s : sardines) {
        int sx = s.x;
        int sy = s.y;
        // Check if s is inside the original bounding box
        bool in_original = (sx >= x_min_m && sx <= x_max_m && sy >= y_min_m && sy <= y_max_m);
        if (!in_original) continue; // This should not happen

        // Adjust x range
        int x1a = x_min_m;
        int x2a = sx - 1;
        if (x1a <= x2a) {
            vector<int> rect = {x1a, x2a, y_min_m, y_max_m};
            candidates.push_back(rect);
        }
        x1a = sx + 1;
        x2a = x_max_m;
        if (x1a <= x2a) {
            vector<int> rect = {x1a, x2a, y_min_m, y_max_m};
            candidates.push_back(rect);
        }

        // Adjust y range
        int y1a = y_min_m;
        int y2a = sy - 1;
        if (y1a <= y2a) {
            vector<int> rect = {x_min_m, x_max_m, y1a, y2a};
            candidates.push_back(rect);
        }
        y1a = sy + 1;
        y2a = y_max_m;
        if (y1a <= y2a) {
            vector<int> rect = {x_min_m, x_max_m, y1a, y2a};
            candidates.push_back(rect);
        }
    }

    // Now, evaluate each candidate
    int best_a_minus_b = -1;
    vector<int> best_rect;
    for (const auto& rect : candidates) {
        int x1 = rect[0];
        int x2 = rect[1];
        int y1 = rect[2];
        int y2 = rect[3];

        if (x1 >= x2 || y1 >= y2) continue;

        int a = count_points(x1, x2, y1, y2, mackerels);
        int b = count_points(x1, x2, y1, y2, sardines);

        int current = a - b;
        if (current > best_a_minus_b) {
            best_a_minus_b = current;
            best_rect = {x1, x2, y1, y2};
        }
    }

    // If no valid candidates found (should not happen, but fallback)
    if (best_rect.empty()) {
        // Use original bounding box if valid (should be handled)
        x1_orig = x_min_m;
        x2_orig = x_max_m;
        y1_orig = y_min_m;
        y2_orig = y_max_m;
        best_rect = {x1_orig, x2_orig, y1_orig, y2_orig};
    }

    // Output the best rectangle
    cout << 4 << endl;
    cout << best_rect[0] << " " << best_rect[3] << endl;
    cout << best_rect[1] << " " << best_rect[3] << endl;
    cout << best_rect[1] << " " << best_rect[2] << endl;
    cout << best_rect[0] << " " << best_rect[2] << endl;

    return 0;
}

