        cout << 0 << " " << 0 << endl;
        return 0;
    }

    // Compute bounding box of mackerels
    int xmin_m = mackerels[0].first;
    int xmax_m = mackerels[0].first;
    int ymin_m = mackerels[0].second;
    int ymax_m = mackerels[0].second;
    for (auto p : mackerels) {
        xmin_m = min(xmin_m, p.first);
        xmax_m = max(xmax_m, p.first);
        ymin_m = min(ymin_m, p.second);
        ymax_m = max(ymax_m, p.second);
    }

    // Check perimeter of the initial box
    int width = xmax_m - xmin_m;
    int height = ymax_m - ymin_m;
    int perimeter = 2 * (width + height);
    if (perimeter > 400000) {
        // Try to find a smaller valid rectangle
        // For simplicity, adjust to a smaller box
        // Reduce width and height by some amount
        int new_width = min(width, 200000);
        int new_height = min(height, 200000);
        int new_perimeter = 2 * (new_width + new_height);
        if (new_perimeter > 400000) {
            // Another adjustment
            new_width = min(width, (400000 / 2));
            new_height = min(height, (400000 - 2 * new_width) / 2);
        }
        // Assume we shrink the box by some amount to fit the perimeter
        int new_xmin = xmin_m + (width - new_width) / 2;
        int new_xmax = new_xmin + new_width;
        int new_ymin = ymin_m + (height - new_height) / 2;
        int new_ymax = new_ymin + new_height;
        xmin_m = new_xmin;
        xmax_m = new_xmax;
        ymin_m = new_ymin;
        ymax_m = new_ymax;
    }

    int sardines_in_box = 0;
    for (auto s : sardines) {
        if (s.first >= xmin_m && s.first <= xmax_m && s.second >= ymin_m && s.second <= ymax_m) {
            sardines_in_box++;
        }
    }
    int current_score = max(0, N - sardines_in_box);
    int best_xmin = xmin_m;
    int best_xmax = xmax_m;
    int best_ymin = ymin_m;
    int best_ymax = ymax_m;

    // Now, for each sardine in the original box, try adjusting the box
    for (auto s : sardines) {
        if (s.first >= xmin_m && s.first <= xmax_m && s.second >= ymin_m && s.second <= ymax_m) {
            // Try adjusting left boundary
            int new_xmin = max(s.first + 1, xmin_m);
            if (new_xmin <= xmax_m) {
                // Compute mackerels in new box
