    if (initial_x1 == initial_x2) {
        initial_x1 -= 1;
        initial_x2 += 1;
    }
    if (initial_y1 == initial_y2) {
        initial_y1 -= 1;
        initial_y2 += 1;
    }

    // Compute number of sardines in initial rectangle
    int initial_b = 0;
    for (const auto& p : sardines) {
        if (p.x >= initial_x1 && p.x <= initial_x2 && p.y >= initial_y1 && p.y <= initial_y2) {
            ++initial_b;
        }
