                best_a = a_right;
                best_b = b_right;
                best_x1 = new_x1_right;
                best_x2 = new_x2_right;
                best_y1 = new_y1_right;
                best_y2 = new_y2_right;
            }
        }

        // Try adjusting y range to exclude sardine (bottom)
        int new_x1_bottom = initial_x1;
        int new_x2_bottom = initial_x2;
        int new_y1_bottom = sy + 1;
        int new_y2_bottom = initial_y2;
        if (new_x1_bottom <= new_x2_bottom && new_y1_bottom <= new_y2_bottom) {
            int a_bottom = 0;
