#include <bits/stdc++.h>
using namespace std;

struct Rect {
    int x_min, x_max, y_min, y_max;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    int N;
    cin >> N;

    vector<pair<int, int>> mackerels, sardines;
    for (int i = 0; i < N; ++i) {
        int x, y;
        cin >> x >> y;
        mackerels.emplace_back(x, y);
    }
    for (int i = 0; i < N; ++i) {
        int x, y;
        cin >> x >> y;
        sardines.emplace_back(x, y);
    }

    int x_min_m = INT_MAX, x_max_m = INT_MIN;
    int y_min_m = INT_MAX, y_max_m = INT_MIN;
    for (auto& m : mackerels) {
        x_min_m = min(x_min_m, m.first);
        x_max_m = max(x_max_m, m.first);
        y_min_m = min(y_min_m, m.second);
        y_max_m = max(y_max_m, m.second);
    }

    vector<Rect> candidates;

    // Original bounding box
    Rect orig;
    orig.x_min = x_min_m;
    orig.x_max = x_max_m;
    orig.y_min = y_min_m;
    orig.y_max = y_max_m;

    int total_len_orig = 2 * ((orig.x_max - orig.x_min) + (orig.y_max - orig.y_min));
    if (total_len_orig <= 400000) {
        candidates.push_back(orig);
    }

    // Collect sardines in original bounding box
    vector<pair<int, int>> s_in_box;
    for (auto& s : sardines) {
        if (s.first >= x_min_m && s.first <= x_max_m && s.second >= y_min_m && s.second <= y_max_m) {
            s_in_box.push_back(s);
        }
    }

    // Generate candidates for each sardine in s_in_box
    for (auto& s : s_in_box) {
        int x_s = s.first;
        int y_s = s.second;

        // Candidate 1: x_max = x_s - 1
        Rect r1;
        r1.x_min = x_min_m;
        r1.x_max = x_s - 1;
        r1.y_min = y_min_m;
        r1.y_max = y_max_m;
        if (r1.x_min <= r1.x_max && r1.y_min <= r1.y_max) {
            int width = r1.x_max - r1.x_min;
            int height = r1.y_max - r1.y_min;
            if (2 * (width + height) <= 400000) {
                candidates.push_back(r1);
            }
        }

        // Candidate 2: x_min = x_s + 1
        Rect r2;
        r2.x_min = x_s + 1;
        r2.x_max = x_max_m;
        r2.y_min = y_min_m;
        r2.y_max = y_max_m;
        if (r2.x_min <= r2.x_max && r2.y_min <= r2.y_max) {
            int width = r2.x_max - r2.x_min;
            int height = r2.y_max - r2.y_min;
            if (2 * (width + height) <= 400000) {
                candidates.push_back(r2);
            }
        }

        // Candidate 3: y_max = y_s - 1
        Rect r3;
        r3.x_min = x_min_m;
        r3.x_max = x_max_m;
        r3.y_min = y_min_m;
        r3.y_max = y_s - 1;
        if (r3.y_min <= r3.y_max && r3.x_min <= r3.x_max) {
            int width = r3.x_max - r3.x_min;
            int height = r3.y_max - r3.y_min;
            if (2 * (width + height) <= 400000) {
                candidates.push_back(r3);
            }
        }

        // Candidate 4: y_min = y_s + 1
        Rect r4;
        r4.x_min = x_min_m;
        r4.x_max = x_max_m;
        r4.y_min = y_s + 1;
        r4.y_max = y_max_m;
        if (r4.y_min <= r4.y_max && r4.x_min <= r4.x_max) {
            int width = r4.x_max - r4.x_min;
            int height = r4.y_max - r4.y_min;
            if (2 * (width + height) <= 400000) {
                candidates.push_back(r4);
            }
        }
    }

    int best_d = -1;
    Rect best_rect = {0, 0, 0, 0};

    for (auto& rect : candidates) {
        int count_m = 0;
        for (auto& m : mackerels) {
            if (m.first >= rect.x_min && m.first <= rect.x_max && m.second >= rect.y_min && m.second <= rect.y_max) {
                count_m++;
            }
        }
        int count_s = 0;
        for (auto& s : sardines) {
            if (s.first >= rect.x_min && s.first <= rect.x_max && s.second >= rect.y_min && s.second <= rect.y_max) {
                count_s++;
            }
        }
        int current_d = count_m - count_s;
        if (current_d > best_d) {
            best_d = current_d;
            best_rect = rect;
        }
    }

    // Output the best rectangle
    if (best_rect.x_min <= best_rect.x_max && best_rect.y_min <= best_rect.y_max) {
        cout << 4 << endl;
        cout << best_rect.x_min << ' ' << best_rect.y_min << endl;
        cout << best_rect.x_max << ' ' << best_rect.y_min << endl;
        cout << best_rect.x_max << ' ' << best_rect.y_max << endl;
        cout << best_rect.x_min << ' ' << best_rect.y_max << endl;
    } else {
        // Fallback, though this case should not occur with valid candidates
        cout << 4 << endl;
        cout << x_min_m << ' ' << y_min_m << endl;
        cout << x_max_m << ' ' << y_min_m << endl;
        cout << x_max_m << ' ' << y_max_m << endl;
        cout << x_min_m << ' ' << y_max_m << endl;
    }

    return 0;
}

#include <iostream>
