#include <tuple>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    int N;
    cin >> N;

    vector<pair<int, int>> mackerels, sardines;
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    // Compute initial rectangle for mackerels
    int min_x = mackerels[0].first;
    int max_x = mackerels[0].first;
    int min_y = mackerels[0].second;
    int max_y = mackerels[0].second;
    for (auto& m : mackerels) {
        min_x = min(min_x, m.first);
        max_x = max(max_x, m.first);
        min_y = min(min_y, m.second);
        max_y = max(max_y, m.second);
    }

    // Check if initial_rect is valid
    int delta_x = max_x - min_x;
    int delta_y = max_y - min_y;
    int total_length_initial = 2 * (delta_x + delta_y);
    bool initial_rect_valid = (total_length_initial <= 400000);

    vector<tuple<int, int, int, int>> candidates;

    if (initial_rect_valid) {
        candidates.push_back({min_x, max_x, min_y, max_y});
    }

    // Generate candidates based on sardines inside the initial rectangle
    for (auto& s : sardines) {
        if (s.first >= min_x && s.first <= max_x && s.second >= min_y && s.second <= max_y) {
            // 1. adjust x_high to s.x -1
            int new_x_low = min_x;
            int new_x_high = s.first - 1;
            int new_y_low = min_y;
            int new_y_high = max_y;
            if (new_x_high >= new_x_low && new_y_high >= new_y_low) {
                int delta_x1 = new_x_high - new_x_low;
                int delta_y1 = new_y_high - new_y_low;
                if (2 * (delta_x1 + delta_y1) <= 400000) {
                    candidates.push_back({new_x_low, new_x_high, new_y_low, new_y_high});
                }
            }

            // 2. adjust x_low to s.x +1
            new_x_low = s.first + 1;
            new_x_high = max_x;
            new_y_low = min_y;
            new_y_high = max_y;
            if (new_x_high >= new_x_low && new_y_high >= new_y_low) {
                int delta_x2 = new_x_high - new_x_low;
                int delta_y2 = new_y_high - new_y_low;
                if (2 * (delta_x2 + delta_y2) <= 400000) {
                    candidates.push_back({new_x_low, new_x_high, new_y_low, new_y_high});
                }
            }

            // 3. adjust y_high to s.y -1
            new_x_low = min_x;
            new_x_high = max_x;
            new_y_low = min_y;
            new_y_high = s.second - 1;
            if (new_x_high >= new_x_low && new_y_high >= new_y_low) {
                int delta_x3 = new_x_high - new_x_low;
                int delta_y3 = new_y_high - new_y_low;
                if (2 * (delta_x3 + delta_y3) <= 400000) {
                    candidates.push_back({new_x_low, new_x_high, new_y_low, new_y_high});
                }
            }

            // 4. adjust y_low to s.y +1
            new_x_low = min_x;
            new_x_high = max_x;
            new_y_low = s.second + 1;
            new_y_high = max_y;
            if (new_x_high >= new_x_low && new_y_high >= new_y_low) {
                int delta_x4 = new_x_high - new_x_low;
                int delta_y4 = new_y_high - new_y_low;
                if (2 * (delta_x4 + delta_y4) <= 400000) {
                    candidates.push_back({new_x_low, new_x_high, new_y_low, new_y_high});
                }
            }
        }
    }

    // Evaluate all candidates
    int best_score = 0;
    tuple<int, int, int, int> best_rect;

    for (auto& c : candidates) {
        int x_low = get<0>(c);
        int x_high = get<1>(c);
        int y_low = get<2>(c);
        int y_high = get<3>(c);

        int m_count = 0;
        for (auto& m : mackerels) {
            if (m.first >= x_low && m.first <= x_high && m.second >= y_low && m.second <= y_high) {
                ++m_count;
            }
        }

        int s_count = 0;
        for (auto& s : sardines) {
            if (s.first >= x_low && s.first <= x_high && s.second >= y_low && s.second <= y_high) {
                ++s_count;
            }
        }

        int current_score = max(0, m_count - s_count + 1);
        if (current_score > best_score) {
            best_score = current_score;
            best_rect = c;
        }
    }

    // Output the best rect
    int x_low = get<0>(best_rect);
    int x_high = get<1>(best_rect);
    int y_low = get<2>(best_rect);
    int y_high = get<3>(best_rect);

    cout << 4 << endl;
    cout << x_low << " " << y_low << endl;
    cout << x_high << " " << y_low << endl;
    cout << x_high << " " << y_high << endl;
    cout << x_low << " " << y_high << endl;

    return 0;
}

