using namespace std;

struct RectCandidate {
    int x1, y1, x2, y2, m_count;
};

int main() {
    int N;
    cin >> N;
    vector<pair<int, int>> mackerels, sardines;
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    vector<RectCandidate> candidates;

    // Initial candidate: minimal rectangle of all mackerels
    if (!mackerels.empty()) {
        int x1 = mackerels[0].first;
        int x2 = mackerels[0].first;
        int y1 = mackerels[0].second;
        int y2 = mackerels[0].second;
        for (const auto& p : mackerels) {
            x1 = min(x1, p.first);
            x2 = max(x2, p.first);
            y1 = min(y1, p.second);
            y2 = max(y2, p.second);
        }
        candidates.push_back({x1, y1, x2, y2, (int)mackerels.size()});
    }

    // Generate other candidates by filtering for each sardine
    for (const auto& sardine : sardines) {
        int sx = sardine.first;
        int sy = sardine.second;

        // Filter for x < sx
        vector<pair<int, int>> filtered;
        for (const auto& p : mackerels) {
            if (p.first < sx) {
                filtered.push_back(p);
            }
        }
        if (!filtered.empty()) {
            int x1 = filtered[0].first;
            int x2 = sx - 1;
            int y1 = filtered[0].second;
            int y2 = filtered[0].second;
            for (const auto& p : filtered) {
                x1 = min(x1, p.first);
                x2 = max(x2, p.first);
                y1 = min(y1, p.second);
                y2 = max(y2, p.second);
            }
            candidates.push_back({x1, y1, x2, y2, (int)filtered.size()});
        }

        // Filter for x > sx
        filtered.clear();
        for (const auto& p : mackerels) {
            if (p.first > sx) {
                filtered.push_back(p);
            }
        }
        if (!filtered.empty()) {
            int x1 = sx + 1;
            int x2 = filtered[0].first;
            int y1 = filtered[0].second;
            int y2 = filtered[0].second;
            for (const auto& p : filtered) {
                x1 = min(x1, p.first);
                x2 = max(x2, p.first);
                y1 = min(y1, p.second);
                y2 = max(y2, p.second);
            }
            candidates.push_back({x1, y1, x2, y2, (int)filtered.size()});
        }

        // Filter for y < sy
        filtered.clear();
        for (const auto& p : mackerels) {
            if (p.second < sy) {
                filtered.push_back(p);
            }
        }
        if (!filtered.empty()) {
            int x1 = filtered[0].first;
            int x2 = filtered[0].first;
            int y1 = filtered[0].second;
            int y2 = sy - 1;
            for (const auto& p : filtered) {
                x1 = min(x1, p.first);
                x2 = max(x2, p.first);
                y1 = min(y1, p.second);
                y2 = max(y2, p.second);
            }
            candidates.push_back({x1, y1, x2, y2, (int)filtered.size()});
        }

        // Filter for y > sy
        filtered.clear();
        for (const auto& p : mackerels) {
            if (p.second > sy) {
                filtered.push_back(p);
            }
        }
        if (!filtered.empty()) {
            int x1 = filtered[0].first;
            int x2 = filtered[0].first;
            int y1 = sy + 1;
            int y2 = filtered[0].second;
            for (const auto& p : filtered) {
                x1 = min(x1, p.first);
                x2 = max(x2, p.first);
                y1 = min(y1, p.second);
                y2 = max(y2, p.second);
            }
            candidates.push_back({x1, y1, x2, y2, (int)filtered.size()});
        }
    }

    // Find the best candidate
    int best_score = 0;
    int best_x1 = 0, best_y1 = 0, best_x2 = 0, best_y2 = 0;
    int best_m = 0;

    for (const auto& candidate : candidates) {
        int x1 = candidate.x1;
        int y1 = candidate.y1;
        int x2 = candidate.x2;
        int y2 = candidate.y2;
        int m_count = candidate.m_count;

        // Count sardines in this rectangle
        int s_count = 0;
        for (const auto& s : sardines) {
            if (s.first >= x1 && s.first <= x2 && s.second >= y1 && s.second <= y2) {
                s_count++;
            }
        }
        int score = max(0, m_count - s_count + 1);
        if (score > best_score) {
            best_score = score;
            best_x1 = x1;
            best_y1 = y1;
            best_x2 = x2;
            best_y2 = y2;
            best_m = m_count;
        }
    }

    // Output the best candidate
    cout << 4 << endl;
    cout << best_x1 << " " << best_y1 << endl;
    cout << best_x2 << " " << best_y1 << endl;
    cout << best_x2 << " " << best_y2 << endl;
    cout << best_x1 << " " << best_y2 << endl;

    return 0;
}

