#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>
using namespace std;

struct Point {
    int x, y;
};

int main() {
    int N;
    cin >> N;

    vector<Point> mackerels;
    vector<Point> sardines;

    for (int i = 0; i < N; i++) {
        int x, y;
        cin >> x >> y;
        mackerels.push_back({x, y});
    }

    for (int i = 0; i < N; i++) {
        int x, y;
        cin >> x >> y;
        sardines.push_back({x, y});
    }

    // Compute initial bounding box for mackerels
    int x_min_m = mackerels[0].x;
    int x_max_m = mackerels[0].x;
    int y_min_m = mackerels[0].y;
    int y_max_m = mackerels[0].y;

    for (auto p : mackerels) {
        x_min_m = min(x_min_m, p.x);
        x_max_m = max(x_max_m, p.x);
        y_min_m = min(y_min_m, p.y);
        y_max_m = max(y_max_m, p.y);
    }

    // Function to count points in a rectangle
    auto count_mackerels = [&](int x1, int x2, int y1, int y2) {
        int count = 0;
        for (auto p : mackerels) {
            if (p.x >= x1 && p.x <= x2 && p.y >= y1 && p.y <= y2) {
                count++;
            }
        }
        return count;
    };

    auto count_sardines = [&](int x1, int x2, int y1, int y2) {
        int count = 0;
        for (auto p : sardines) {
            if (p.x >= x1 && p.x <= x2 && p.y >= y1 && p.y <= y2) {
                count++;
            }
        }
        return count;
    };

    // Initial rectangle
    int a_initial = N;
    int b_initial = count_sardines(x_min_m, x_max_m, y_min_m, y_max_m);
    int best_score = max(0, a_initial - b_initial + 1);
    int best_x1 = x_min_m, best_x2 = x_max_m, best_y1 = y_min_m, best_y2 = y_max_m;

    // Try adjustments for each sardine
    for (auto s : sardines) {
        int x_s = s.x;
        int y_s = s.y;

        // Adjust x_high to exclude s.x
        if (x_s > x_min_m) {
            int new_x_high = x_s - 1;
            if (new_x_high >= x_min_m) {
                int a = count_mackerels(x_min_m, new_x_high, y_min_m, y_max_m);
                int b = count_sardines(x_min_m, new_x_high, y_min_m, y_max_m);
                int current_score = max(0, a - b + 1);
                if (current_score > best_score) {
                    best_score = current_score;
                    best_x1 = x_min_m;
                    best_x2 = new_x_high;
                    best_y1 = y_min_m;
                    best_y2 = y_max_m;
                }
            }
        }

        // Adjust x_low to exclude s.x
        if (x_s < x_max_m) {
            int new_x_low = x_s + 1;
            if (new_x_low <= x_max_m) {
                int a = count_mackerels(new_x_low, x_max_m, y_min_m, y_max_m);
                int b = count_sardines(new_x_low, x_max_m, y_min_m, y_max_m);
                int current_score = max(0, a - b + 1);
                if (current_score > best_score) {
                    best_score = current_score;
                    best_x1 = new_x_low;
                    best_x2 = x_max_m;
                    best_y1 = y_min_m;
                    best_y2 = y_max_m;
                }
            }
        }

        // Adjust y_high to exclude s.y
        if (y_s > y_min_m) {
            int new_y_high = y_s - 1;
            if (new_y_high >= y_min_m) {
                int a = count_mackerels(x_min_m, x_max_m, y_min_m, new_y_high);
                int b = count_sardines(x_min_m, x_max_m, y_min_m, new_y_high);
                int current_score = max(0, a - b + 1);
                if (current_score > best_score) {
                    best_score = current_score;
                    best_x1 = x_min_m;
                    best_x2 = x_max_m;
                    best_y1 = y_min_m;
                    best_y2 = new_y_high;
                }
            }
        }

        // Adjust y_low to exclude s.y
        if (y_s < y_max_m) {
            int new_y_low = y_s + 1;
            if (new_y_low <= y_max_m) {
                int a = count_mackerels(x_min_m, x_max_m, new_y_low, y_max_m);
                int b = count_sardines(x_min_m, x_max_m, new_y_low, y_max_m);
                int current_score = max(0, a - b + 1);
                if (current_score > best_score) {
                    best_score = current_score;
                    best_x1 = x_min_m;
                    best_x2 = x_max_m;
                    best_y1 = new_y_low;
                    best_y2 = y_max_m;
                }
            }
        }

        // Adjust both x and y to exclude s.x and s.y
        if (x_s > x_min_m && y_s > y_min_m) {
            int new_x_high = x_s - 1;
            int new_y_high = y_s - 1;
            if (new_x_high >= x_min_m && new_y_high >= y_min_m) {
                int a = count_mackerels(x_min_m, new_x_high, y_min_m, new_y_high);
                int b = count_sardines(x_min_m, new_x_high, y_min_m, new_y_high);
                int current_score = max(0, a - b + 1);
                if (current_score > best_score) {
                    best_score = current_score;
                    best_x1 = x_min_m;
                    best_x2 = new_x_high;
                    best_y1 = y_min_m;
                    best_y2 = new_y_high;
                }
            }
        }

        if (x_s < x_max_m && y_s < y_max_m) {
            int new_x_low = x_s + 1;
            int new_y_low = y_s + 1;
            if (new_x_low <= x_max_m && new_y_low <= y_max_m) {
                int a = count_mackerels(new_x_low, x_max_m, new_y_low, y_max_m);
                int b = count_sardines(new_x_low, x_max_m, new_y_low, y_max_m);
                int current_score = max(0, a - b + 1);
                if (current_score > best_score) {
                    best_score = current_score;
                    best_x1 = new_x_low;
                    best_x2 = x_max_m;
                    best_y1 = new_y_low;
                    best_y2 = y_max_m;
                }
            }
        }

        // Additional combinations
        if (x_s > x_min_m && y_s < y_max_m) {
            int new_x_high = x_s - 1;
            int new_y_low = y_s + 1;
            if (new_x_high >= x_min_m && new_y_low <= y_max_m) {
                int a = count_mackerels(x_min_m, new_x_high, new_y_low, y_max_m);
                int b = count_sardines(x_min_m, new_x_high, new_y_low, y_max_m);
                int current_score = max(0, a - b + 1);
                if (current_score > best_score) {
                    best_score = current_score;
                    best_x1 = x_min_m;
                    best_x2 = new_x_high;
                    best_y1 = new_y_low;
                    best_y2 = y_max_m;
                }
            }
        }

        if (x_s < x_max_m && y_s > y_min_m) {
            int new_x_low = x_s + 1;
            int new_y_high = y_s - 1;
            if (new_x_low <= x_max_m && new_y_high >= y_min_m) {
                int a = count_mackerels(new_x_low, x_max_m, y_min_m, new_y_high);
                int b = count_sardines(new_x_low, x_max_m, y_min_m, new_y_high);
                int current_score = max(0, a - b + 1);
                if (current_score > best_score) {
                    best_score = current_score;
                    best_x1 = new_x_low;
                    best_x2 = x_max_m;
                    best_y1 = y_min_m;
                    best_y2 = new_y_high;
                }
            }
        }
    }

    // Output the best rectangle
    cout << 4 << endl;
    cout << best_x1 << " " << best_y1 << endl;
    cout << best_x2 << " " << best_y1 << endl;
    cout << best_x2 << " " << best_y2 << endl;
    cout << best_x1 << " " << best_y2 << endl;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Point {
    int x, y;
};

int main() {
    int N;
    cin >> N;
    vector<Point> all_points;
    for (int i = 0; i < 2 * N; ++i) {
        int x, y;
        cin >> x >> y;
        all_points.push_back({x, y});
    }

    vector<Point> mackerels;
    vector<Point> sardines;
    for (int i = 0; i < N; ++i) {
        mackerels.push_back(all_points[i]);
    }
    for (int i = N; i < 2 * N; ++i) {
        sardines.push_back(all_points[i]);
    }

    int best_score = 0;
    int best_x1 = 0, best_y1 = 0, best_x2 = 0, best_y2 = 0;

    // Compute the overall rectangle
    int x_min_all = INT_MAX;
    int x_max_all = INT_MIN;
    int y_min_all = INT_MAX;
    int y_max_all = INT_MIN;
    for (const auto& p : mackerels) {
        x_min_all = min(x_min_all, p.x);
        x_max_all = max(x_max_all, p.x);
        y_min_all = min(y_min_all, p.y);
        y_max_all = max(y_max_all, p.y);
    }

    int width_all = x_max_all - x_min_all;
    int height_all = y_max_all - y_min_all;
    int perimeter_all = 2 * (width_all + height_all);
    if (perimeter_all <= 400000) {
        int count_sardines_all = 0;
        for (const auto& s : sardines) {
            if (s.x >= x_min_all && s.x <= x_max_all && s.y >= y_min_all && s.y <= y_max_all) {
                ++count_sardines_all;
            }
        }
        int a_all = N;
        int b_all = count_sardines_all;
        int score_all = max(0, a_all - b_all + 1);
        if (score_all > best_score) {
            best_score = score_all;
            best_x1 = x_min_all;
            best_y1 = y_min_all;
            best_x2 = x_max_all;
            best_y2 = y_max_all;
        }
    }

    // Check each mackerel's expanded rectangle
    const int expand = 100;
    for (const auto& m : mackerels) {
        int mx = m.x;
        int my = m.y;

        int x1_rect = max(0, mx - expand);
        int x2_rect = min(100000, mx + expand);
        int y1_rect = max(0, my - expand);
        int y2_rect = min(100000, my + expand);

        int width = x2_rect - x1_rect;
        int height = y2_rect - y1_rect;
        int perimeter = 2 * (width + height);
        if (perimeter > 400000) {
            continue;
        }

        int a_rect = 0;
        for (const auto& p : mackerels) {
            if (p.x >= x1_rect && p.x <= x2_rect && p.y >= y1_rect && p.y <= y2_rect) {
                ++a_rect;
            }
        }

        int b_rect = 0;
        for (const auto& s : sardines) {
            if (s.x >= x1_rect && s.x <= x2_rect && s.y >= y1_rect && s.y <= y2_rect) {
                ++b_rect;
            }
        }

        int score_rect = max(0, a_rect - b_rect + 1);
        if (score_rect > best_score) {
            best_score = score_rect;
            best_x1 = x1_rect;
            best_y1 = y1_rect;
            best_x2 = x2_rect;
