    int min_x_m = INT_MAX, max_x_m = INT_MIN, min_y_m = INT_MAX, max_y_m = INT_MIN;
    for (const auto &p : mackerels) {
        min_x_m = min(min_x_m, p.x);
        max_x_m = max(max_x_m, p.x);
        min_y_m = min(min_y_m, p.y);
        max_y_m = max(max_y_m, p.y);
    }

    int best_a = 0, best_b = 0;
    int best_score = 0;
    int best_x1 = min_x_m, best_x2 = max_x_m, best_y1 = min_y_m, best_y2 = max_y_m;

    // Initial candidate: initial bounding box
    int a = N;
    int cnt_sardines = 0;
    for (const auto &p : sardines) {
        if (p.x >= best_x1 && p.x <= best_x2 && p.y >= best_y1 && p.y <= best_y2) {
            cnt_sardines++;
        }
    }
    int score = max(0, a - cnt_sardines + 1);
    best_score = score;
    best_a = a;
    best_b = cnt_sardines;
    best_x1 = min_x_m;
    best_x2 = max_x_m;
    best_y1 = min_y_m;
    best_y2 = max_y_m;

    // Generate other candidates by adjusting for each sardine
    for (const auto &s : sardines) {
        int xs = s.x, ys = s.y;

        // Check if sardine is inside the initial rectangle
        bool in_rect = false;
        if (xs >= best_x1 && xs <= best_x2 && ys >= best_y1 && ys <= best_y2) {
            in_rect = true;
        }

        if (!in_rect) {
            continue;
        }

        // Generate four possible rectangles
        vector<tuple<int, int, int, int>> candidates;
        // Left
        int x1_left = best_x1;
        int x2_left = xs - 1;
        if (x1_left <= x2_left) {
            candidates.emplace_back(x1_left, x2_left, best_y1, best_y2);
        }
        // Right
        int x1_right = xs + 1;
        int x2_right = best_x2;
        if (x1_right <= x2_right) {
            candidates.emplace_back(x1_right, x2_right, best_y1, best_y2);
        }
        // Bottom
        int y1_bottom = best_y1;
        int y2_bottom = ys - 1;
        if (y1_bottom <= y2_bottom) {
            candidates.emplace_back(best_x1, best_x2, y1_bottom, y2_bottom);
        }
        // Top
        int y1_top = ys + 1;
        int y2_top = best_y2;
        if (y1_top <= y2_top) {
            candidates.emplace_back(best_x1, best_x2, y1_top, y2_top);
        }

        for (auto [x1, x2, y1, y2] : candidates) {
            int cnt_m = 0;
            for (const auto &p : mackerels) {
                if (p.x >= x1 && p.x <= x2 && p.y >= y1 && p.y <= y2) {
                    cnt_m++;
                }
            }
            int cnt_s = 0;
            for (const auto &p : sardines) {
                if (p.x >= x1 && p.x <= x2 && p.y >= y1 && p.y <= y2) {
                    cnt_s++;
                }
            }
            int current_score = max(0, cnt_m - cnt_s + 1);
            if (current_score > best_score) {
                best_score = current_score;
                best_a = cnt_m;
                best_b = cnt_s;
                best_x1 = x1;
                best_x2 = x2;
                best_y1 = y1;
                best_y2 = y2;
            }
        }
    }

    // Output the best rectangle
    cout << 4 << endl;
    cout << best_x1 << ' ' << best_y1 << endl;
    cout << best_x2 << ' ' << best_y1 << endl;
    cout << best_x2 << ' ' << best_y2 << endl;
    cout << best_x1 << ' ' << best_y2 << endl;

    return 0;
}

