    int min_y = mackerels[0].second;
    int max_y = mackerels[0].second;
    for (auto p : mackerels) {
        min_x = min(min_x, p.first);
        max_x = max(max_x, p.first);
        min_y = min(min_y, p.second);
        max_y = max(max_y, p.second);
    }

    // Adjust initial rectangle to ensure it's valid
    if (min_x == max_x || min_y == max_y) {
        if (min_x == max_x) {
            min_x--;
            max_x++;
        }
        if (min_y == max_y) {
            min_y--;
            max_y++;
        }
    }

    // Function to count points inside a rectangle
    auto count_points = [&](vector<pair<int, int>>& points, int x1, int y1, int x2, int y2) -> int {
        int cnt = 0;
        for (auto p : points) {
            if (p.first >= x1 && p.first <= x2 && p.second >= y1 && p.second <= y2) {
                ++cnt;
            }
        }
        return cnt;
    };

    // Initial rectangle
    int a_initial = N;
    int s_initial = 0;
    for (auto p : sardines) {
        if (p.first >= min_x && p.first <= max_x && p.second >= min_y && p.second <= max_y) {
