                    best_x1 = min_x;
                    best_x2 = max_x;
                    best_y1 = y1_rect3;
                    best_y2 = y2_rect3;
                }
            }

            // rect4: y_low = min_y, y_high = s.second - 1; x same
            int y1_rect4 = min_y;
            int y2_rect4 = s.second - 1;
            if (y1_rect4 < y2_rect4 && x1_rect1 < x2_rect1) {
                int a_rect = count_points(mackerels, min_x, y1_rect4, max_x, y2_rect4);
                int s_rect = count_points(sardines, min_x, y1_rect4, max_x, y2_rect4);
                int current_score = a_rect - s_rect;
                if (current_score > best_score) {
                    best_score = current_score;
                    best_x1 = min_x;
                    best_x2 = max_x;
                    best_y1 = y1_rect4;
                    best_y2 = y2_rect4;
                }
            }
        }
    }

    // Output the best rectangle
    cout << 4 << endl;
    cout << best_x1 << " " << best_y1 << endl;
