        if (i < N) {
            mackerels.push_back({x, y});
        } else {
            sardines.push_back({x, y});
        }
    }

    int x_max_m = 0, x_min_m = 100000;
    int y_max_m = 0, y_min_m = 100000;
    for (auto p : mackerels) {
        x_max_m = max(x_max_m, p.first);
        x_min_m = min(x_min_m, p.first);
        y_max_m = max(y_max_m, p.second);
        y_min_m = min(y_min_m, p.second);
    }

    int x_max_s = 0, x_min_s = 100000;
    int y_max_s = 0, y_min_s = 100000;
    for (auto p : sardines) {
        x_max_s = max(x_max_s, p.first);
        x_min_s = min(x_min_s, p.first);
        y_max_s = max(y_max_s, p.second);
        y_min_s = min(y_min_s, p.second);
    }

    bool found = false;
    int x_left = 0, x_right = 100000;
    int y_bottom = 0, y_top = 100000;

    // Check vertical separation
    if (x_max_m < x_min_s) {
        x_left = 0;
        x_right = x_max_m;
        y_bottom = y_min_m;
        y_top = y_max_m;
        found = true;
    } else if (x_min_m > x_max_s) {
        x_left = x_min_m;
        x_right = 100000;
        y_bottom = y_min_m;
        y_top = y_max_m;
        found = true;
    } else {
        // Check horizontal separation
        if (y_max_m < y_min_s) {
            y_bottom = 0;
            y_top = y_max_m;
            x_left = x_min_m;
            x_right = x_max_m;
            found = true;
        } else if (y_min_m > y_max_s) {
            y_bottom = y_min_m;
            y_top = 100000;
            x_left = x_min_m;
            x_right = x_max_m;
            found = true;
        }
    }

    if (found) {
        cout << 4 << endl;
        cout << x_left << " " << y_bottom << endl;
        cout << x_right << " " << y_bottom << endl;
        cout << x_right << " " << y_top << endl;
        cout << x_left << " " << y_top << endl;
