        int x_left_b = x_min_m;
        int x_right_b = x_max_m;
        int y_bottom_b = y_min_m;
        int y_top_b = y_max_m;

        // Expand x if needed
        if (x_left_b == x_right_b) {
            x_right_b = x_left_b + 1;
            if (x_right_b > 100000) {
                x_right_b = 100000;
            }
        }
        if (x_right_b < x_left_b) {
            swap(x_left_b, x_right_b);
        }

        // Expand y if needed
        if (y_bottom_b == y_top_b) {
            y_top_b = y_bottom_b + 1;
            if (y_top_b > 100000) {
                y_top_b = 100000;
            }
        }
        if (y_top_b < y_bottom_b) {
            swap(y_bottom_b, y_top_b);
        }

        cout << 4 << endl;
        cout << x_left_b << " " << y_bottom_b << endl;
        cout << x_right_b << " " << y_bottom_b << endl;
        cout << x_right_b << " " << y_top_b << endl;
        cout << x_left_b << " " << y_top_b << endl;
    }

    return 0;
